def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = next(c for c in range(w) if all(grid[r][c] == grid[0][c] for r in range(h)))
    n = min(sep, w - sep - 1)

    # The repeated color in each panel is its background; the other color
    # marks cells to be carried into the combined pattern.
    left_counts = {}
    right_counts = {}
    for row in grid:
        for c in range(n):
            left_counts[row[c]] = left_counts.get(row[c], 0) + 1
            x = row[sep + 1 + c]
            right_counts[x] = right_counts.get(x, 0) + 1
    left_mark = min(left_counts, key=left_counts.get)
    right_mark = min(right_counts, key=right_counts.get)

    return [
        [2 if row[c] == left_mark or row[sep + 1 + c] == right_mark else 3
         for c in range(n)]
        for row in grid
    ]
